import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static final int MAX_LIMITS = 1000007;
    static final long MOD_VAL = 1000000007L;
    static int p_val, k_val;
    static int[] cnts = new int[MAX_LIMITS];
    static int[] visiteds = new int[MAX_LIMITS];
    static int[] nums = new int[MAX_LIMITS];

    static void dfs_traverse(int x, int start) {
        int count = 1;
        while ((long)k_val * x % p_val != start) {
            x = (int)((long)k_val * x % p_val);
            visiteds[x] = 1;
            count++;
        }
        nums[count]++;
    }

    static boolean isPrimeNumber(int x) {
        if (x < 2) return false;
        for (int i = 2; i * i <= x; i++) {
            if (x % i == 0) return false;
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        p_val = sc.nextInt();
        k_val = sc.nextInt();

        if (k_val == 0) {
            long prod = 1;
            for (int i = 1; i < p_val; i++) {
                prod = (prod * p_val) % MOD_VAL;
            }
            System.out.println(prod);
            sc.close();
            return;
        }

        for (int i = 0; i < p_val; i++) {
            if (visiteds[i] == 0) {
                dfs_traverse(i, i);
            }
        }

        List<Integer> divisors_vec = new ArrayList<>();
        for (int i = 1; i <= p_val; i++) {
            if (nums[i] != 0) {
                divisors_vec.add(i);
            }
        }

        long final_product = 1;
        for (int i = 0; i < divisors_vec.size(); i++) {
            long sum_t = 0;
            int divisor_i = divisors_vec.get(i);
            for (int j = 0; j < divisors_vec.size(); j++) {
                int divisor_j = divisors_vec.get(j);
                if ((long)divisor_j * divisor_j > divisor_i) {
                    break;
                }
                if (divisor_i % divisor_j == 0) {
                    int a = divisor_i / divisor_j;
                    int b = divisor_j;
                    sum_t += (long)a * nums[a];
                    if (a != b) {
                        sum_t += (long)b * nums[b];
                    }
                    sum_t %= MOD_VAL;
                }
            }
            int count = nums[divisor_i];
            for (int j = 0; j < count; j++) {
                final_product = (final_product * sum_t) % MOD_VAL;
            }
        }

        System.out.println(final_product);
        sc.close();
    }
}
